#!/usr/bin/env bash
# Prints the Homebrew formula for one tlschecker release (#215).
#
#   formula.sh <version> <base-url> <dist-dir>
#
# <base-url> is where the release archives are downloaded from: the GitHub
# release, or a file:// directory when the publish workflow test-installs a
# pull request's build. <dist-dir> holds the archives' .sha256 files. The
# license is read from Cargo.toml, so the formula follows it.
set -euo pipefail

if [[ $# -ne 3 ]]; then
  echo "usage: $0 <version> <base-url> <dist-dir>" >&2
  exit 2
fi
version=$1 base_url=${2%/} dist=$3
root=$(cd "$(dirname "$0")/../.." && pwd)

sha() {
  local file="$dist/tlschecker-$1.tar.gz.sha256"
  if [[ ! -s $file ]]; then
    echo "missing $file" >&2
    exit 1
  fi
  cut -d' ' -f1 "$file"
}

# Assigned before the heredoc: a failing $(…) inside it would not stop the
# script.
macos_arm=$(sha macos-aarch64)
macos_intel=$(sha macos-x86_64)
linux_arm=$(sha linux-aarch64)
linux_intel=$(sha linux-x86_64)

# SPDX "A OR B" is `license any_of: ["A", "B"]` in a formula.
license=$(sed -n 's/^license *= *"\(.*\)"/\1/p' "$root/Cargo.toml")
if [[ -z $license ]]; then
  echo "no license in $root/Cargo.toml" >&2
  exit 1
elif [[ $license == *" OR "* ]]; then
  license="any_of: [\"${license// OR /\", \"}\"]"
else
  license="\"$license\""
fi

cat <<EOF
# Generated by the tlschecker release workflow (.github/homebrew/formula.sh in
# jbovet/tlschecker). Do not edit: the next release overwrites it.
class Tlschecker < Formula
  desc "TLS/SSL certificate checker: expiry, chain, revocation and grade"
  homepage "https://github.com/jbovet/tlschecker"
  version "$version"
  license $license

  on_macos do
    on_arm do
      url "$base_url/tlschecker-macos-aarch64.tar.gz"
      sha256 "$macos_arm"
    end
    on_intel do
      url "$base_url/tlschecker-macos-x86_64.tar.gz"
      sha256 "$macos_intel"
    end
  end

  on_linux do
    on_arm do
      url "$base_url/tlschecker-linux-aarch64.tar.gz"
      sha256 "$linux_arm"
    end
    on_intel do
      url "$base_url/tlschecker-linux-x86_64.tar.gz"
      sha256 "$linux_intel"
    end
  end

  def install
    bin.install "tlschecker"
    generate_completions_from_executable(bin/"tlschecker", "--completions",
                                         shells: [:bash, :zsh, :fish])
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/tlschecker --version")
  end
end
EOF
